/**
 * Monday.com Node - Version 2
 * Discriminator: resource=board, operation=createBoard
 */


interface Credentials {
  mondayComApi: CredentialReference;
  mondayComOAuth2Api: CredentialReference;
}

/** Create a new board, optionally in a specific workspace or from a template */
export type MondayComV2BoardCreateBoardParams = {
  resource: 'board';
  operation: 'createBoard';
  authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
/**
 * The name of the new board
 */
    boardName: string | Expression<string>;
/**
 * Who can see the board: public = everyone in the account, private = invited members, shareable = including guests
 * @default public
 */
    boardKind?: 'private' | 'public' | 'share' | Expression<string>;
/**
 * Options
 * @default {}
 */
    createBoardOptions?: {
    /** The description of the new board
     */
    description?: string | Expression<string>;
    /** The folder to create the board in. Select a workspace first — the list shows that workspace’s folders. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
     * @loadOptionsMethod getCreateBoardWorkspaceFolders
     */
    folderId?: string | Expression<string>;
    /** The users and/or teams to set as board owners. The creating user is always an owner. In expression mode, pass a comma-separated string of user IDs and/or &lt;code&gt;team:&lt;ID&gt;&lt;/code&gt; values.
     * @default {}
     */
    ownerIds?: {
        /** Entries
     */
    rows?: Array<{
      /** User or Team
       * @searchListMethod searchUsersAndTeams
       * @default {"mode":"list","value":""}
       */
      user?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
    }>;
  };
    /** The users and/or teams to subscribe to the board. In expression mode, pass a comma-separated string of user IDs and/or &lt;code&gt;team:&lt;ID&gt;&lt;/code&gt; values.
     * @default {}
     */
    subscriberIds?: {
        /** Entries
     */
    rows?: Array<{
      /** User or Team
       * @searchListMethod searchUsersAndTeams
       * @default {"mode":"list","value":""}
       */
      user?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
    }>;
  };
    /** Create the board from this board template. monday has no API to list templates, so copy the numeric ID from the template’s Template Center URL (enable Developer mode in monday.labs to see IDs). The template must be accessible to the API user.
     */
    templateId?: string | Expression<string>;
    /** The workspace to create the board in. To use the account’s Main workspace, leave this unset — the API does not list it as a selectable workspace. Picking a workspace here also loads its folders into the Folder option.
     * @searchListMethod searchWorkspaces
     * @default {"mode":"list","value":""}
     */
    workspaceId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
  };
};

export type MondayComV2BoardCreateBoardNode = {
  type: 'n8n-nodes-base.mondayCom';
  version: 2;
  config: NodeConfig<MondayComV2BoardCreateBoardParams> & { credentials?: Credentials };
};